parameters.query:
select r."roomNumber", r.capacity 
from "Room" r
order by r."roomNumber";

select cg."groupNum" , c.code, c."name"
from "CourseGroup" cg inner join "Course" c ON cg.course_id = c.id
order by cg."groupNum" ;

parameters.jsCode:
const enrollments = $items("Query Enrollments").map(i => i.json);
const rooms = $items("Query Rooms").map(i => i.json);
const courseGroupRows = $items("Query Course Group").map(i => i.json);

// group courseGroup เป็น array ตาม groupNum
const grouped = courseGroupRows.reduce((acc, row) => {
  if (!acc[row.groupNum]) acc[row.groupNum] = { groupNum: row.groupNum, courses: [] };
  acc[row.groupNum].courses.push({ code: row.code, name: row.name });
  return acc;
}, {});

const courseGroups = Object.values(grouped).sort((a,b) => a.groupNum - b.groupNum);

return [{
  json: {
    config: $items("Edit Fields")[0].json,
    enrollments,
    rooms,
    courseGroups,
  }
}];

const config = $json.config;

// runKey แบบอ่านง่าย + ไม่ซ้ำง่าย (เวลารัน + user)
const now = new Date();
const pad = (n) => String(n).padStart(2, "0");
const ts =
  now.getFullYear() +
  pad(now.getMonth() + 1) +
  pad(now.getDate()) + "_" +
  pad(now.getHours()) +
  pad(now.getMinutes()) +
  pad(now.getSeconds());

const runKey = `${config.username}_${ts}`;

return [{
  json: {
    ...$json,
    runKey,
  }
}];

// Expect 1 item ที่มี:
// - config
// - enrollments (array)
// - courseGroups (array of { groupNum, courses: [{code,name}] })
// - examRunId, runKey

const data = items[0].json;

// 1) ทำ map: courseCode -> groupNum
const codeToGroupNum = new Map();
const courseGroups = Array.isArray(data.courseGroups) ? data.courseGroups : [];

for (const g of courseGroups) {
  const groupNum = g.groupNum;
  const courses = Array.isArray(g.courses) ? g.courses : [];
  for (const c of courses) {
    if (c?.code) codeToGroupNum.set(String(c.code).trim(), groupNum);
  }
}

// 2) แตก enrollments เป็น candidate items
const enrollments = Array.isArray(data.enrollments) ? data.enrollments : [];

const out = enrollments.map((e) => {
  // ระวังชื่อ field: บาง query ของคุณใช้ classname/departmentname เป็นตัวเล็ก
  const className = e.className ?? e.classname ?? null;
  const departmentName = e.departmentName ?? e.departmentname ?? null;

  const courseCode = String(e.courseCode ?? e.coursecode ?? "").trim();
  const groupNum = codeToGroupNum.has(courseCode) ? codeToGroupNum.get(courseCode) : null;

  return {
    json: {
      examRunId: data.examRunId ?? data.examRunID ?? null,
      runKey: data.runKey ?? null,

      enrollmentId: e.enrollment_id ?? e.enrollmentId ?? e.id ?? null,
      classId: e.class_id ?? e.classId ?? null,
      courseId: e.course_id ?? e.courseId ?? null,

      className,
      departmentName,

      amount: e.amount ?? null,
      courseCode: courseCode || null,
      courseName: e.courseName ?? e.coursename ?? null,
      duration: Number(e.duration ?? 0),

      groupNum, // สำคัญ: เอาไว้จัดพร้อมกัน
      // ช่องว่างสำหรับตอนจัดจริง
      timeStart: null,
      timeEnd: null,
      roomNumber: null,
      violations: [],
    },
  };
});

// กันกรณี enrollments ว่าง (ตามกติกาคุณไม่อยากได้ [])
if (out.length === 0) {
  return [{ json: { error: "No enrollments found", examRunId: data.examRunId ?? null, runKey: data.runKey ?? null } }];
}

return out;

// Build Time Slots (PATCH)
// ต้องการให้ 1 enrollment = 1 unit เท่านั้น (ไม่แตกตาม groupNum)

return items.map(i => ({
  json: {
    ...i.json,
    // กันพลาด: ถ้ามี field taskKey/groupIndex/groupSize จากของเดิม ให้ไม่ใช้
    taskKey: undefined,
    groupIndex: undefined,
    groupSize: undefined,

    // ใช้ student_count จาก amount ตรง ๆ
    studentCount: i.json.amount ?? i.json.studentCount ?? 0,
  }
}));

// Prepare ExamUnit Rows (1 item => 1 ExamUnit)
// ต้องตั้ง Mode: Run Once for Each Item

return {
  json: {
    runkey: $json.runKey,
    enrollment_id: $json.enrollmentId,
    class_id: $json.classId,
    course_id: $json.courseId,

    // จำนวนเด็ก = amount ของ class
    student_count: $json.amount ?? 0,

    duration: Number($json.duration ?? 0),

    meta: {
      className: $json.className ?? null,
      departmentName: $json.departmentName ?? null,
      courseCode: $json.courseCode ?? null,
      courseName: $json.courseName ?? null,
      groupNum: $json.groupNum ?? null,
    }
  }
};

const rows = items.map(i => i.json);

// ---- config จาก workflow ----
const cfg = $('Attach Run Id').first().json.config;
const examStart = new Date(cfg.examStart);
const examEnd   = new Date(cfg.examEnd);

// ---- fixed time definition ----
const FIXED_SLOTS = {
  AM: [
    [8*60+30,  9*60+30],
    [9*60+30, 10*60+30],
    [10*60+30,11*60+30],
    [11*60+30,12*60+30],
  ],
  PM: [
    [13*60+30,14*60+30],
    [14*60+30,15*60+30],
    [15*60+30,16*60+30],
  ]
};

const DAY_START_MIN   = 8*60 + 30;
const LUNCH_START_MIN = 12*60 + 30;
const LUNCH_END_MIN   = 13*60 + 30;
const DAY_END_MIN     = 16*60 + 30;

// ---- capacity (rooms) ----
const ROOM_CAPACITY = 32; // 34 - reserve 2

// ---- NEW CONFIG: MAX EXAM DAYS PER CLASS ----
const MAX_EXAM_DAYS = 3; 

function dateOnly(d){ return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
function addDays(d, n){ const x=new Date(d); x.setDate(x.getDate()+n); return x; }

const days = [];
for (let d=dateOnly(examStart); d<=dateOnly(examEnd); d=addDays(d,1)) days.push(d);

function blockKey(r){
  if (r.groupNum !== null && r.groupNum !== undefined) return `G:${r.groupNum}`;
  return `C:${String(r.courseCode).trim()}`;
}

// ---- build blocks ----
const blocksMap = new Map();
for (const r of rows){
  const k = blockKey(r);
  if (!blocksMap.has(k)) {
    blocksMap.set(k, { key:k, duration:Number(r.duration||0), members:[], roomsNeeded:0 });
  }
  const b = blocksMap.get(k);
  b.members.push(r);
  b.duration = Math.max(b.duration, Number(r.duration||0));
}

// ---- roomsNeeded ----
for (const b of blocksMap.values()){
  const set = new Set();
  for (const m of b.members){
    const cn = (m.className ?? "").trim();
    if (cn) set.add(cn);
  }
  b.roomsNeeded = Math.max(1, set.size);
}

// ---- sort blocks ----
const blocks = [...blocksMap.values()].sort((a,b) => 
  (b.roomsNeeded - a.roomsNeeded) || 
  (b.members.length - a.members.length) ||
  (b.duration - a.duration)
);

// ---- helpers ----
function overlaps(aStart,aEnd,bStart,bEnd){ return aStart < bEnd && bStart < aEnd; }

const classBusy = new Map();
const roomBusy  = new Map();
const sessionLoad = days.map(()=>({ AM:0, PM:0 }));

// ⭐ NEW: Track Used Days per Class
const classUsedDays = new Map(); // Map<className, Set<dayIndex>>

function sessionOf(startMin){
  return (startMin < LUNCH_START_MIN) ? "AM" : "PM";
}

function canPlaceForClass(className, dayIndex, startMin, endMin){
  const key = className || "__NULL__";
  const arr = classBusy.get(key) || [];
  for (const it of arr){
    if (it.dayIndex === dayIndex && overlaps(startMin,endMin,it.startMin,it.endMin)) {
      return false;
    }
  }
  return true;
}

// ⭐ NEW: Check if adding this day exceeds limit
function canPlaceMaxDays(className, dayIndex) {
  const key = className || "__NULL__";
  if (!classUsedDays.has(key)) return true; // ยังไม่เคยสอบเลย

  const usedSet = classUsedDays.get(key);
  // ถ้าวันนี้เคยมีสอบแล้ว -> ลงเพิ่มได้ (ไม่นับวันเพิ่ม)
  if (usedSet.has(dayIndex)) return true;

  // ถ้าเป็นวันใหม่ -> เช็คว่าเกินโควตาไหม
  return usedSet.size < MAX_EXAM_DAYS;
}

function addBusy(className, dayIndex, startMin, endMin){
  const key = className || "__NULL__";
  if (!classBusy.has(key)) classBusy.set(key, []);
  classBusy.get(key).push({ dayIndex, startMin, endMin });
}

// ⭐ NEW: Register day usage
function addUsedDay(className, dayIndex) {
  const key = className || "__NULL__";
  if (!classUsedDays.has(key)) classUsedDays.set(key, new Set());
  classUsedDays.get(key).add(dayIndex);
}

function canPlaceForRooms(dayIndex, startMin, endMin, roomsNeeded){
  const arr = roomBusy.get(dayIndex) || [];
  for (const it of arr){
    if (overlaps(startMin,endMin,it.startMin,it.endMin)) {
      if (it.rooms + roomsNeeded > ROOM_CAPACITY) return false;
    }
  }
  return true;
}

function addRoomBusy(dayIndex, startMin, endMin, roomsNeeded){
  if (!roomBusy.has(dayIndex)) roomBusy.set(dayIndex, []);
  roomBusy.get(dayIndex).push({ startMin, endMin, rooms: roomsNeeded });
}

// ✅ FIXED SLOT ONLY
function* sessionSlots(duration, session){
  for (const [s,e] of FIXED_SLOTS[session] || []) {
    if (e - s === duration) {
      yield [s,e];
    }
  }
}

function makeDate(day, minuteOfDay){
  const d=new Date(day);
  d.setHours(0,0,0,0);
  d.setMinutes(minuteOfDay);
  return d;
}
function fmt(dt){
  const pad=n=>String(n).padStart(2,'0');
  return `${dt.getFullYear()}-${pad(dt.getMonth()+1)}-${pad(dt.getDate())} ${pad(dt.getHours())}:${pad(dt.getMinutes())}`;
}

// ---- place blocks ----
const placed = new Map();

for (const b of blocks){
  let best = null;

  const candidates = [];
  for (let dayIndex=0; dayIndex<days.length; dayIndex++){
    candidates.push({ dayIndex, session:"AM", load:sessionLoad[dayIndex].AM });
    candidates.push({ dayIndex, session:"PM", load:sessionLoad[dayIndex].PM });
  }
  // sort by load (balance workload)
  candidates.sort((x,y)=>x.load-y.load);

  for (const c of candidates){

    // ⭐ NEW CHECK: Check Max Days Constraint First
    // ถ้าสมาชิกคนใดคนหนึ่งใน block นี้ สอบครบ 3 วันไปแล้ว (และวันนี้เป็นวันใหม่) -> ข้าม
    let daysQuotaOk = true;
    for (const m of b.members) {
      if (!canPlaceMaxDays(m.className, c.dayIndex)) {
        daysQuotaOk = false;
        break;
      }
    }
    if (!daysQuotaOk) continue; 
    // --------------------------------------------------

    for (const [s,e] of sessionSlots(b.duration, c.session)){
      let ok = true;

      for (const m of b.members){
        if (!canPlaceForClass(m.className, c.dayIndex, s, e)){
          ok=false; break;
        }
      }
      if (!ok) continue;
      if (!canPlaceForRooms(c.dayIndex, s, e, b.roomsNeeded)) continue;

      best = { dayIndex:c.dayIndex, session:c.session, s, e };
      break;
    }
    if (best) break;
  }

  if (!best){
    // fallback (rare case: force placement on day 0)
    const s = FIXED_SLOTS.AM[0][0];
    const e = FIXED_SLOTS.AM[0][1];
    placed.set(b.key, { dayIndex:0, startMin:s, forced:true });

    for (const m of b.members) {
        addBusy(m.className, 0, s, e);
        addUsedDay(m.className, 0); // Still mark used day even if forced
    }
    addRoomBusy(0, s, e, b.roomsNeeded);
    sessionLoad[0].AM += b.duration * b.roomsNeeded;
  } else {
    placed.set(b.key, { dayIndex:best.dayIndex, startMin:best.s, forced:false });

    for (const m of b.members) {
        addBusy(m.className, best.dayIndex, best.s, best.e);
        addUsedDay(m.className, best.dayIndex); // ⭐ NEW: Mark day as used
    }
    addRoomBusy(best.dayIndex, best.s, best.e, b.roomsNeeded);
    sessionLoad[best.dayIndex][best.session] += b.duration * b.roomsNeeded;
  }
}

// ---- output ----
const out = [];
for (const r of rows){
  const k = blockKey(r);
  const b = placed.get(k);
  const day = days[b.dayIndex];
  const start = b.startMin;
  const end = start + Number(r.duration||0);

  const violations = [];
  if (b.forced) violations.push(`Forced placement for block ${k}`);

  out.push({
    exam_plan_id: r.exam_plan_id,
    className: r.className,
    departmentName: r.departmentName,
    courseCode: r.courseCode,
    courseName: r.courseName,
    duration: Number(r.duration||0),
    roomNumber: 0,
    timeStart: fmt(makeDate(day, start)),
    timeEnd: fmt(makeDate(day, end)),
    violations
  });
}

return out.map(x => ({ json: x }));

const plans = $('Load ExamPlan Slots').all().map(i => i.json);

// รองรับชื่อคอลัมน์ห้องหลายแบบ
const roomsRaw = $('Query Rooms').all().map(i => i.json.roomNumber ?? i.json.roomnumber ?? i.json.room_no);

// ---------- helpers ----------
function toDate(x) {
  const d = new Date(x);
  return Number.isNaN(d.getTime()) ? null : d;
}

function roomSortKey(v) {
  const s = String(v ?? '').trim();
  const n = Number(s);
  if (s !== '' && !Number.isNaN(n)) return { type: 0, n, s };
  return { type: 1, n: 0, s };
}

function sortRooms(arr) {
  arr.sort((a, b) => {
    const ka = roomSortKey(a);
    const kb = roomSortKey(b);
    if (ka.type !== kb.type) return ka.type - kb.type;
    if (ka.type === 0) return ka.n - kb.n;
    return ka.s.localeCompare(kb.s);
  });
}

// แทรกห้องกลับเข้า availableRooms (รักษา sort)
function insertSorted(arr, room) {
  // rooms ~ 34 ห้อง ใช้ linear insert ได้ ไม่ช้า
  const keyR = roomSortKey(room);
  let i = 0;
  while (i < arr.length) {
    const keyI = roomSortKey(arr[i]);
    const cmp =
      (keyR.type - keyI.type) ||
      (keyR.type === 0 ? (keyR.n - keyI.n) : keyR.s.localeCompare(keyI.s));
    if (cmp <= 0) break;
    i++;
  }
  arr.splice(i, 0, room);
}

// ---------- normalize rooms ----------
let availableRooms = roomsRaw
  .map(x => (x === null || x === undefined) ? null : String(x).trim())
  .filter(x => x && x.length > 0);

sortRooms(availableRooms);

// busyRooms = [{ endMs, room }]
let busyRooms = [];
function releaseRoomsUntil(startMs) {
  // เอาห้องที่ end <= start ออก แล้วคืนเข้า available
  // (busyRooms มีน้อย เลย sort ทุกครั้งได้)
  busyRooms.sort((a, b) => a.endMs - b.endMs);
  while (busyRooms.length > 0 && busyRooms[0].endMs <= startMs) {
    const freed = busyRooms.shift();
    insertSorted(availableRooms, freed.room);
  }
}

// ---------- normalize plans ----------
function getStart(p){ return p.timestart ?? p.timeStart ?? p.timestart_th; }
function getEnd(p){ return p.timeend ?? p.timeEnd ?? p.timeend_th; }

const seen = new Set();
const items = [];

for (const p of plans) {
  const sd = toDate(getStart(p));
  const ed = toDate(getEnd(p));
  if (!sd || !ed) continue;

  const classId = p.class_id ?? p.classId;
  const uniqKey = `${classId}|${sd.toISOString()}|${ed.toISOString()}`;
  if (seen.has(uniqKey)) continue;
  seen.add(uniqKey);

  items.push({
    exam_plan_id: p.exam_plan_id ?? p.id ?? null, // แนะนำให้มีเพื่อ update ง่าย
    runkey: p.runkey,
    class_id: classId,
    departmentname: p.departmentname ?? '',
    timestart: getStart(p),
    timeend: getEnd(p),
    startMs: sd.getTime(),
    endMs: ed.getTime()
  });
}

// เรียงตามเวลาเริ่ม
items.sort((a,b)=>
  (a.startMs - b.startMs) ||
  (a.endMs - b.endMs) ||
  String(a.departmentname).localeCompare(String(b.departmentname)) ||
  (Number(a.class_id) - Number(b.class_id))
);

// ---------- core: assign rooms with "keep same room if contiguous" ----------
const lastRoomByClass = new Map(); // class_id -> { room, lastEndMs }
const updates = [];

for (const it of items) {
  releaseRoomsUntil(it.startMs);

  const last = lastRoomByClass.get(it.class_id);

  // นิยาม "คาบติดกัน" = คาบก่อนหน้าจบตรงกับคาบนี้เริ่ม
  const isContiguous = last && last.lastEndMs === it.startMs;

  let chosen = null;
  let status = 'OK';

  if (last) {
    // ถ้าเป็นคาบติดกัน -> "พยายาม" ใช้ห้องเดิมก่อน
    // ถ้าไม่ติดกัน -> ก็ยัง prefer ห้องเดิม (ลดการย้ายห้อง) แต่ไม่บังคับ
    const preferRoom = last.room;

    const idx = availableRooms.findIndex(r => r === preferRoom);
    if (idx !== -1) {
      chosen = availableRooms.splice(idx, 1)[0]; // เอาห้องเดิมออกจาก available
      status = 'OK';
    } else {
      // ห้องเดิมไม่ว่าง
      chosen = availableRooms.shift() ?? null;
      if (chosen === null) status = 'NA';
      else status = isContiguous ? 'CHANGED' : 'OK'; // ติดกันแต่ต้องเปลี่ยนห้อง
    }
  } else {
    // class นี้ยังไม่เคยได้ห้องมาก่อน
    chosen = availableRooms.shift() ?? null;
    status = chosen ? 'OK' : 'NA';
  }

  if (chosen) {
    busyRooms.push({ endMs: it.endMs, room: chosen });
    lastRoomByClass.set(it.class_id, { room: chosen, lastEndMs: it.endMs });
  } else {
    // ถ้า NA ก็อัปเดต lastEndMs เฉย ๆ ไม่ควรล็อกห้อง
    lastRoomByClass.set(it.class_id, { room: last?.room ?? null, lastEndMs: it.endMs });
  }

  updates.push({
    exam_plan_id: it.exam_plan_id,
    runkey: it.runkey,
    class_id: it.class_id,
    timestart: it.timestart,
    timeend: it.timeend,
    roomnumber: chosen,
    room_status: status
  });
}

return updates.map(x => ({ json: x }));

parameters.query:
UPDATE "ExamPlan"
SET roomnumber = '{{$json.roomnumber}}'
WHERE id = {{$json.exam_plan_id}}
RETURNING id AS exam_plan_id, classname AS "className", departmentname AS "departmentName", coursecode AS "courseCode", coursename AS "courseName", duration, roomnumber AS "roomNumber", (SELECT r.floor FROM "Room" r WHERE r."roomNumber" = "ExamPlan".roomnumber) AS "roomFloor", timestart AS "timeStart", timeend AS "timeEnd";

parameters.jsCode:
const merged = {};

// merge QA flags
for (const item of items) {
  Object.assign(merged, item.json);
}

// collect QA boolean flags
const qaEntries = Object.entries(merged)
  .filter(([key, value]) =>
    key.startsWith('qa_') &&
    (value === true || value === false)
  );

// if no QA at all → fail safe
const all_pass =
  qaEntries.length > 0 &&
  qaEntries.every(([, value]) => value === true);

// failed QA keys
const failed = qaEntries
  .filter(([, value]) => value === false)
  .map(([key]) => key);

// optional: friendly error map (frontend optional)
const qaMessages = {
  qa_course_same_time_pass: "Course scheduled at the same time",
  qa_coursegroup_same_time_pass: "Course group scheduled at the same time",
  qa_room_no_overlap_pass: "Room overlap detected",
  qa_room_assigned_pass: "Some exam plans have no room assigned",
  qa_time_window_pass: "Exam scheduled outside allowed time window",
  qa_continuous_over_4h_pass: "Class has exams longer than 4 hours continuously"
};

const failedDetails = failed.map(key => ({
  code: key,
  message: qaMessages[key] || key
}));

return [{
  json: {
    ...merged,
    all_pass,
    failed_qas: failed,
    failed_details: failedDetails   // optional แต่ดีมาก
  }
}];

