(function() {
  // 1. Get QA results from the summary node
  const auditResult = $("QA Summary").first().json; 

  // 2. Return rows after room assignments were persisted
  const finalSchedule = $("Update to ExamPlan").all().map(i => i.json);

  // 3. Safety Check
  if (!auditResult) {
    return { 
      "status": "error", 
      "message": "QA Summary node data is missing" 
    };
  }

  // 4. Return the structure your React Frontend expects
  return {
    "status": auditResult.all_pass ? "success" : "failed_validation",
    "message": auditResult.all_pass ? "Exam schedule generated successfully" : "Validation failed",
    "data": {
      "isValid": auditResult.all_pass,
      "schedule": finalSchedule,
      "auditReport": {
        "course_same_time": auditResult.qa_course_same_time_pass,
        "course_group_same_time": auditResult.qa_coursegroup_same_time_pass,
        "room_overlap": auditResult.qa_room_no_overlap_pass
      }
    }
  };
})()
}}

